def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, 20.0))

    prev_bids = []
    bob_bid = None
    cindy_bid = None
    urgent_opp = 0
    rich_opp = 0

    for agent_id, opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            prev_bids.append(bid)
            if agent_id == 'Bob':
                bob_bid = bid
            elif agent_id == 'Cindy':
                cindy_bid = bid

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    if bob_bid is not None:
        moderate_prev = bob_bid
    elif prev_bids:
        moderate_prev = sorted(prev_bids)[int(len(prev_bids) // 2)]

    if hp <= 2 or no_water_days >= 2:
        if cindy_bid is not None:
            target = min(DAILY_SALARY * 1.55, cindy_bid + 2.0)
        else:
            target = DAILY_SALARY * 1.1
        return float(min(budget, max(1.0, target)))

    if slots >= 2:
        if moderate_prev > 0:
            target = moderate_prev + 2.0
        else:
            target = DAILY_SALARY * 0.62
        if urgent_opp >= 2:
            target += 6.0
        if hp >= 8 and no_water_days == 0:
            target -= 3.0
        return float(min(budget, max(1.0, target)))

    if hp >= 8 and no_water_days == 0:
        if highest_prev >= DAILY_SALARY * 1.3:
            return float(min(budget, 8.0))
        return float(min(budget, 18.0))

    if hp >= 5:
        if bob_bid is not None:
            target = bob_bid + 1.5
        else:
            target = DAILY_SALARY * 0.78
        if cindy_bid is not None and cindy_bid > target + 35 and hp > 6:
            target = min(target, 45.0)
        return float(min(budget, max(1.0, target)))

    target = max(DAILY_SALARY * 0.92, moderate_prev + 3.0)
    if rich_opp >= 2:
        target += 5.0
    return float(min(budget, max(1.0, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction)
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # Pressure estimate: who likely bid high yesterday (Cindy survived with high bids)
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine urgency: if low HP or already accumulating no-water days, bid more.
    # Heuristic: if hp <= 2 or no_water_days >= 2, treat as critical.
    critical = (hp <= 2) or (no_water_days >= 2)

    # Supply scarcity factor: lower supply => bid higher to secure enough water share.
    # Map supply in [15,25] to scarcity in [1.0,0.6]
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = 1.0 - 0.4 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY))
    else:
        scarcity = 1.0
    if scarcity < 0.6:
        scarcity = 0.6
    if scarcity > 1.0:
        scarcity = 1.0

    # Base bid target
    if critical:
        target = DAILY_SALARY * 0.85 * scarcity
    else:
        # If someone was already bidding very high yesterday, slightly undercut to avoid waste.
        # If highest_prev_bid is large, we need to match a fraction.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = max(DAILY_SALARY * 0.55, highest_prev_bid * 0.75)
        else:
            target = max(DAILY_SALARY * 0.45, highest_prev_bid * 0.65)
        target = target * scarcity

    # Budget cap: never exceed budget
    # Also keep some budget for later days: reserve a fraction unless critical.
    reserve_frac = 0.25 if critical else 0.45
    max_affordable = budget * (1.0 - reserve_frac)
    bid = min(float(target), float(max_affordable), float(budget))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    # If supply is extremely low, add a small bump
    if supply <= float(WATER_REQ) + 6.0:
        bid = min(float(budget), bid + DAILY_SALARY * 0.05)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)
    num_active_bidders = num_alive_opponents + 1 # Including myself

    # Calculate available water slots based on current supply
    available_water_slots = int(day_context['supply'] / WATER_REQ)

    # Default bid amount
    bid_amount = DAILY_SALARY * 0.5

    # Strategy 1: No opponents left, bid minimally to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Strategy 2: Critical HP, bid aggressively to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Strategy 3: End game, secure water
    if day_context['day'] >= EPISODE_DAYS - 2:
        # If supply is very low compared to demand, bid very high
        if available_water_slots < num_active_bidders:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            return min(my_status['budget'], DAILY_SALARY * 0.7)

    # Strategy 4: React to yesterday's bids from opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        # Determine competition level
        if available_water_slots < num_active_bidders: # High competition
            if my_status['hp'] <= 4: # Moderate HP, need to be competitive
                bid_amount = max(highest_prev_bid + 5, DAILY_SALARY * 0.7)
            else: # Good HP, still competitive but can be slightly less aggressive
                bid_amount = max(average_prev_bid * 1.1, DAILY_SALARY * 0.6)
        else: # Low competition (supply is abundant)
            if my_status['hp'] <= 4: # Still need water, but can be cheaper
                bid_amount = max(average_prev_bid * 0.9, DAILY_SALARY * 0.45)
            else: # Good HP, save money
                bid_amount = max(average_prev_bid * 0.8, DAILY_SALARY * 0.35)
    else:
        # Day 1 or no bids from yesterday, use a default strategy
        if available_water_slots < num_active_bidders: # High competition
            bid_amount = DAILY_SALARY * 0.65
        else: # Low competition
            bid_amount = DAILY_SALARY * 0.4

    # Ensure bid is within budget and non-negative
    return max(0.0, min(my_status['budget'], bid_amount))

